INSERT INTO `tbl_breaking_news` (`id`, `text`, `image`, `link_url`, `sort_order`, `status`, `created_at`) VALUES
(1, 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', 'uploads/breaking/jp_6a509e8bd097a3.51794927.png', '', 0, 1, '2026-06-25 12:36:51'),
(2, 'தமிழ்நாட்டில் கனமழை எச்சரிக்கை – 10 மாவட்டங்களில் ரெட் அலர்ட்', NULL, NULL, 1, 1, '2026-06-29 06:00:00'),
(3, 'சதரங்க ஒலிம்பியாட் 2026: இந்தியா 5 தங்கப் பதக்கம் வென்று சாதனை', NULL, NULL, 2, 1, '2026-06-27 21:00:00'),
(4, 'சென்சக்ஸ் 85,000 புள்ளிகளை தாண்டியது – புதிய சரித்திர உச்சம்', NULL, NULL, 3, 1, '2026-06-29 09:30:00'),
(5, 'இந்தியா – இங்கிலாந்து முதல் டெஸ்ட் தொடங்கியது | லார்ட்ஸ் மைதானம்', NULL, NULL, 4, 1, '2026-06-29 06:30:00'),
(6, 'ரஷ்யா-உக்ரைன் சமாதான பேச்சுவார்த்தை: ஐ.நா. வரவேற்பு', NULL, NULL, 5, 1, '2026-06-28 20:30:00'),
(7, 'TNPSC குரூப் 2 தேர்வு செப்டம்பர் 14 | விண்ணப்பிக்க கடைசி நாள் ஜூலை 31', NULL, NULL, 6, 1, '2026-06-27 11:30:00'),
(8, 'யூரோ 2026: ஸ்பெயின் அரையிறுதியில் | யாமால் இரட்டை கோல்', NULL, NULL, 7, 1, '2026-06-28 22:30:00'),
(9, 'குடும்பகுளம் 3, 4 அலகுகள் விரைவில் இயக்கம் – தமிழ்நாட்டில் மின் நெருக்கடி தீரும்', NULL, NULL, 8, 1, '2026-06-27 15:30:00'),
(10, 'தமிழ்நாடு வரவு-செலவு 2026: கடன் தள்ளுபடி, இலவச பேருந்து நீடிப்பு அறிவிப்பு', NULL, NULL, 9, 1, '2026-06-28 08:30:00'),
(11, 'IIT மதுரை: சூரிய ஆற்றல் தண்ணீர் சுத்திகரிப்பு கருவி கண்டுபிடிப்பு – தேசிய விருது', NULL, NULL, 10, 1, '2026-06-25 10:30:00'),
(12, 'திருச்சி விமான நிலையம் 500 கோடி ரூபாய் விரிவாக்கம் – 2028 முடிவு', NULL, NULL, 11, 1, '2026-06-26 11:30:00'),
(13, 'கோயம்புத்தூர் நெடுஞ்சாலை விபத்து: 5 பேர் காயம்', NULL, NULL, 12, 1, '2026-06-29 08:00:00'),
(14, 'மதுரை ஆடி திருவிழா: மாநில அரசு கூடுதல் பாதுகாப்பு ஏற்பாடு', NULL, NULL, 13, 1, '2026-06-27 07:30:00'),
(15, 'DMK-Congress கூட்டணி இடைத் தேர்தல் ஆலோசனை முடிவு', NULL, NULL, 14, 1, '2026-06-28 18:30:00'),
(16, 'நாடாளுமன்றம்: தமிழக மீனவர் பிரச்சினை – வெளியுறவு அமைச்சர் இலங்கையுடன் பேச்சுவார்த்தை', NULL, NULL, 15, 1, '2026-06-28 16:30:00'),
(17, 'இந்தியா AI கொள்கை 2026 வெளியீடு – அரசு திட்டங்களில் AI விரிவாக்கம்', NULL, NULL, 16, 1, '2026-06-28 12:30:00'),
(18, 'வடகிழக்கு பருவமழை அக்டோபர் தொடக்கத்திலேயே வரும் – வானிலை மையம்', NULL, NULL, 17, 1, '2026-06-26 14:30:00'),
(19, 'விஜய் புதிய திரைப்படம் அறிவிப்பு | ஏ.ஆர். ரஹ்மான் இசை | 2027 தீபாவளி', NULL, NULL, 18, 1, '2026-06-27 10:30:00'),
(20, 'கன்னியாகுமரி சுனாமி பயிற்சி: 5,000 பேர் பங்கேற்பு – வெற்றிகரமாக முடிவு', NULL, NULL, 19, 1, '2026-06-26 09:30:00');
