INSERT INTO `tbl_contact_messages` (`id`, `name`, `email`, `phone`, `subject`, `message`, `is_read`, `created_at`) VALUES
(1, 'அருண்குமார்', 'arun@example.com', '9876543210', 'விளம்பர வாய்ப்பு', 'உங்கள் இணையதளத்தில் விளம்பரம் கொடுக்க விரும்புகிறோம். தொடர்புகொள்ளவும்.', 1, '2026-06-25 04:30:00'),
(2, 'கவிதா', 'kavitha@example.com', '9988776655', 'செய்தி அனுப்புதல்', 'என்னுடைய ஊரில் ஒரு முக்கியமான செய்தி நடந்துள்ளது. எப்படி அனுப்புவது?', 0, '2026-06-25 05:30:00'),
(3, 'பாண்டியராஜ்', 'pandy@example.com', '9123456789', 'தொழில்நுட்பக் கேள்வி', 'உங்கள் மொபைல் ஆப் Android-ல் கிடைக்கிறதா?', 1, '2026-06-26 03:30:00'),
(4, 'சரண்யா', 'saranya@example.com', '9765432100', 'கருத்து பதிவு', 'தங்கள் செய்திகள் மிகவும் பயனுள்ளதாக உள்ளன. நன்றி.', 1, '2026-06-26 06:30:00'),
(5, 'நவீன்', 'naveen@example.com', '9000112233', 'Reporter வேலை', 'Reporter ஆக சேர விரும்புகிறேன். தகுதி என்ன?', 0, '2026-06-26 08:30:00'),
(6, 'விமலா', 'vimala@example.com', '8765432109', 'Subscribe பிரச்சினை', 'Email newsletter subscribe செய்தேன் ஆனால் மெயில் வரவில்லை.', 1, '2026-06-27 02:30:00'),
(7, 'கோவிந்தசாமி', 'govinda@example.com', '7654321098', 'செய்தி திருத்தம்', 'நேற்று வெளியான ஒரு செய்தியில் தவறான தகவல் உள்ளது. திருத்தவும்.', 0, '2026-06-27 04:30:00'),
(8, 'மீனாட்சி', 'meena@example.com', '6543210987', 'கூட்டாண்மை ஆர்வம்', 'எங்கள் நிறுவனம் கூட்டாண்மையில் ஆர்வம் உள்ளது. விவரங்கள் வேண்டும்.', 1, '2026-06-27 09:30:00'),
(9, 'திலகன்', 'thilak@example.com', '5432109876', 'நேரடி ஒளிபரப்பு', 'உங்கள் நேரடி ஒளிபரப்பு யூடியூபிலும் வருகிறதா?', 0, '2026-06-28 03:30:00'),
(10, 'சித்ரா', 'chithra@example.com', '9898989898', 'பயனர் பதிவு', 'Jaya Plus-ல் பயனராக பதிவு செய்வது எப்படி?', 1, '2026-06-28 05:30:00'),
(11, 'ஜெயரமன்', 'jayaraman@example.com', '9797979797', 'வாசகர் கடிதம்', 'தமிழக அரசியல் செய்திகளை இன்னும் விரிவாக வெளியிடுங்கள்.', 0, '2026-06-28 07:30:00'),
(12, 'லக்ஷ்மி', 'lakshmi@example.com', '9696969696', 'வேலைவாய்ப்பு', 'Content Writer பணியிடம் இருக்கிறதா?', 0, '2026-06-28 09:30:00'),
(13, 'கார்த்திக்', 'karthik@example.com', '9595959595', 'தொழில்நுட்பம் குறித்து', 'Website-ல் dark mode வசதி சேர்க்க முடியுமா?', 1, '2026-06-28 11:30:00'),
(14, 'பாரதி', 'bharathi@example.com', '9494949494', 'Poll அம்சம்', 'செய்திகளில் reader poll சேர்த்தால் நல்லது.', 0, '2026-06-28 13:30:00'),
(15, 'சேகர்', 'sekar@example.com', '9393939393', 'WhatsApp செய்தி', 'WhatsApp-ல் தினசரி செய்திகள் பெற முடியுமா?', 1, '2026-06-29 02:30:00'),
(16, 'ஆனந்தி', 'anandhi@example.com', '9292929292', 'அன்பளிப்பு விளம்பரம்', 'ஆடி மாத சிறப்பு விளம்பர தொகுப்பு இருக்கிறதா?', 0, '2026-06-29 03:30:00'),
(17, 'சந்திரன்', 'chandran@example.com', '9191919191', 'செய்தி சரிபார்ப்பு', 'Fact check செய்திகளை பிரித்து காட்டுங்கள்.', 0, '2026-06-29 04:30:00'),
(18, 'பவானி', 'bhavani@example.com', '9090909090', 'வீடியோ செய்திகள்', 'செய்திகளுடன் வீடியோவும் சேர்த்தால் நன்றாக இருக்கும்.', 1, '2026-06-29 05:30:00'),
(19, 'ரமேஷ்', 'ramesh@example.com', '8989898989', 'Font size', 'Website-ல் font size பெரிதாக்க option வேண்டும்.', 0, '2026-06-29 06:30:00'),
(20, 'சுலோசனா', 'sulochana@example.com', '8888888888', 'மகளிர் பகுதி', 'பெண்களுக்கென ஒரு தனி செய்தி பகுதி சேர்க்கவும்.', 0, '2026-06-29 07:30:00');
