INSERT INTO `tbl_news` (`id`, `title`, `slug`, `summary`, `content`, `category_id`, `subcategory_id`, `author_id`, `featured_image`, `image_caption`, `tags`, `source`, `is_breaking`, `is_featured`, `is_slider`, `views`, `status`, `meta_title`, `meta_description`, `meta_keywords`, `published_at`, `created_at`, `updated_at`) VALUES
(25, 'அந்த அமைச்சர் அடிக்கடி சர்ச்சையில் சிக்குகிறார்.. தட்டி வையுங்கள்.. இல்ல சிக்கல்தான்.. பறந்த மெசேஜ்', 'அநத-அமசசர-அடககட-சரசசயல-சகககறர-தடட-வயஙகள-இலல-சககலதன-பறநத-மசஜ', 'அந்த அமைச்சர் அடிக்கடி சர்ச்சையில் சிக்குகிறார்.. தட்டி வையுங்கள்.. இல்ல சிக்கல்தான்.. பறந்த மெசேஜ்', '<p>சென்னை: 5 எம்.எல்.ஏ.க்கள் கொண்ட காங்கிரஸ் கட்சியில் 2 பேர் அமைச்சர் ஆகிவிட்டதால் மற்ற 3 எம்.எல்.ஏ.க்களும் சட்டமன்ற காங்கிரஸ் தலைவர் பதவியை கைப்பற்ற அவரவர்கள் லாபியை பயன்படுத்தத் தொடங்கியிருக்கிறார்கள். தமிழக அரசின் பட்ஜெட் கூட்டம் தொடங்கும் போது, சட்டமன்ற காங்கிரஸ் தலைவர் மாற்றப்படுவார் என்கிற பரபரப்பு சத்தியமூர்த்தி பவனில் தொற்றிக்கொண்டிருக்கிறது.<br><br>தமிழக காங்கிரசின் மாநில தலைவராக மாணிக்கம் தாகூர் சமீபத்தில் நியமிக்கப்பட்டார். அவரது தலைமையில் காங்கிரஸ் கட்சியின் செயற்குழு முதல் முறையாக நேற்று நடந்தது. அதில் பல்வேறு விவகாரங்கள் அலசப்பட்டன.<br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e1931f08bc0.11258740.png', 'அமைச்சர்', 'அமைச்சர்', 'அமைச்சர்', 0, 0, 0, 1, 'published', 'அமைச்சர் அடிக்கடி சர்ச்சையில் சிக்குகிறார்', 'அந்த அமைச்சர் அடிக்கடி சர்ச்சையில் சிக்குகிறார்.. தட்டி வையுங்கள்.. இல்ல சிக்கல்தான்.. பறந்த மெசேஜ்', 'அமைச்சர்', '2026-07-08 09:30:28', '2026-07-08 15:00:28', '2026-07-10 12:19:49'),
(26, 'கணக்கு தீர்க்க கரூர் கேஸ்! என்னை சிக்க வைக்க ப்ளான் பண்றாங்க! ஜாமீன் மனுவில் கொட்டித் தீர்த்த செ.பா!', 'கணகக-தரகக-கரர-கஸ-எனன-சகக-வகக-பளன-பணறஙக-ஜமன-மனவல-கடடத-தரதத-சப', 'கணக்கு தீர்க்க கரூர் கேஸ்! என்னை சிக்க வைக்க ப்ளான் பண்றாங்க! ஜாமீன் மனுவில் கொட்டித் தீர்த்த செ.பா!', '<p>சென்னை: தமிழக வெற்றிக் கழக (தவெக) ஊத்தங்கரை தொகுதி எம்.எல்.ஏ. இளையராஜாவிடம் ஆட்சியை கவிழ்க்க ரூ.35 கோடி பேரம் பேசப்பட்டதாக பதிவு செய்யப்பட்டுள்ள வழக்கில், முன்னாள் அமைச்சர் செந்தில் பாலாஜி மற்றும் அவரது சகோதரர் அசோக்குமார் ஆகியோர் சென்னை உயர் நீதிமன்றத்தில் தனித்தனியாக முன் ஜாமீன் மனு தாக்கல் செய்துள்ளனர். இந்த மனுவில் செந்தில் பாலாஜி பல முக்கிய குற்றச்சாட்டுகளை முன்வைத்துள்ளார்.<br><br>குறிப்பாக கரூர் இடைத்தேர்தல் நடைபெற உள்ள சூழலில், கரூர் துயர வழக்கிலும், குதிரை பேர வழக்கிலும் சிக்க வைக்க முயற்சி நடைபெறுகிறது என்று முன்னாள் அமைச்சர் செந்தில் பாலாஜி சென்னை உயர் நீதிமன்றத்தில் தாக்கல் செய்துள்ள முன் ஜாமீன் மனுவில் தெரிவித்துள்ளதாக தகவல் வெளியாகியுள்ளது.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e2170169538.43950481.png', '', 'கணக்கு தீர்க்க கரூர் கேஸ்!', 'கணக்கு தீர்க்க கரூர் கேஸ்!', 0, 0, 0, 1, 'published', 'கணக்கு தீர்க்க கரூர் கேஸ்!', 'கணக்கு தீர்க்க கரூர் கேஸ்!', 'கணக்கு தீர்க்க கரூர் கேஸ்!', '2026-07-08 10:07:33', '2026-07-08 15:37:33', '2026-07-10 12:19:49'),
(27, 'தவெகவுக்குள் நேரடியாக வரும் ஜான் ஆரோக்கியசாமி.. விஜய் கொடுக்கும் பெரிய பொறுப்பு.. அப்செட்டில் ஆதவ்!', 'தவகவககள-நரடயக-வரம-ஜன-ஆரககயசம-வஜய-கடககம-பரய-பறபப-அபசடடல-ஆதவ', 'தவெகவுக்குள் நேரடியாக வரும் ஜான் ஆரோக்கியசாமி.. விஜய் கொடுக்கும் பெரிய பொறுப்பு.. அப்செட்டில் ஆதவ்!', '<p>சென்னை: தவெக துணைத் தலைவர் பதவிக்கு ஜான் ஆரோக்கியசாமி காய் நகர்த்தி வருவதாக தகவல் தெரிய வந்துள்ளது. ஏற்கனவே முதல்வர் விஜய்யுடன் அமைச்சரவை கூட்டத்தில் ஜான் ஆரோக்கியசாமி பங்கேற்று வரும் சூழலில், அடுத்ததாக கட்சியிலும் முக்கிய பொறுப்பை கைப்பற்ற தீவிரமாக இருக்கிறார்.<br><br>அண்மையில் நடந்த அமைச்சரவை கூட்டத்தில் முதல்வர் விஜய்யின் நண்பர் விஷ்ணு ரெட்டி மற்றும் தவெக தேர்தல் வியூக ஆலோசகர் ஜான் ஆரோக்கியசாமி ஆகியோர் பங்கேற்றனர். இந்த விவகாரத்தை கையில் எடுத்த திமுக, அதிமுக மற்றும் பாஜக ஆகிய 3 கட்சிகளும், ஆளுநர் அர்லேகரை நேரில் சந்தித்து புகார் அளித்தனர்.<br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e231469b616.58099996.png', 'தவெகவுக்குள் நேரடியாக வரும் ஜான்', 'தவெகவுக்குள் நேரடியாக வரும் ஜான்', 'தவெகவுக்குள் நேரடியாக வரும் ஜான்', 0, 1, 0, 1, 'published', 'தவெகவுக்குள் நேரடியாக வரும் ஜான் ஆரோக்கியசாமி.. விஜய் கொடுக்கும் பெரிய பொறுப்பு.. அப்செட்டில் ஆதவ்!', 'தவெகவுக்குள் நேரடியாக வரும் ஜான் ஆரோக்கியசாமி.. விஜய் கொடுக்கும் பெரிய பொறுப்பு.. அப்செட்டில் ஆதவ்!', 'தவெகவுக்குள் நேரடியாக வரும் ஜான்', '2026-07-08 10:14:09', '2026-07-08 15:44:09', '2026-07-10 12:19:49'),
(28, 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அகக-ஸதனததல-பசய-கரததன-தவறக-எடததக-களள-வணடம-அமசசர-ரஜமகன', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', '<p>சென்னை: அரசுப் பள்ளி மாணவிகளிடம் தொழில் துறை அமைச்சர் கீர்த்தனா ஆங்கிலத்தில் கேள்வி கேட்ட வீடியோ பெரும் சர்ச்சையை ஏற்படுத்தியுள்ளது. இந்நிலையில், அதுகுறித்து பள்ளிக் கல்வித் துறை அமைச்சர் ராஜ்மோகன் விளக்கம் அளித்துள்ளார். அமைச்சர் எந்தக் காணொளியையும் எடுக்கவில்லை என்றும், மாணவியிடம் அக்கா ஸ்தானத்தில் பேசியதை தவறாகப் புரிந்துகொள்ள வேண்டாம் என்றும் அவர் தெரிவித்துள்ளார்.<br><br>விருதுநகர் மாவட்டம், சிவகாசி அருகே திருத்தங்கலில் உள்ள அரசுப் பெண்கள் மேல்நிலைப் பள்ளியில் தொழில் துறை அமைச்சர் கீர்த்தனா ஆய்வு மேற்கொண்டார். அப்போது, வகுப்பறை ஒன்றுக்குள் சென்ற அமைச்சர் அங்குள்ள மாணவர்களிம் பேசினார். அப்போது, அங்கிருந்த மாணவிகளிடம் ஆங்கிலத்தில் அமைச்சர் சில கேள்விகளைக் கேட்டார். ஆங்கில கேள்விகளுக்கு பதிலளிக்க முடியாமல் மாணவிகள் சிலர் திணறினர்.<br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e24e98e5442.68573418.png', '', '', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 0, 1, 0, 0, 'trash', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', '2026-07-08 10:21:47', '2026-07-08 15:51:47', '2026-07-08 15:52:33'),
(29, 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அகக-ஸதனததல-பசய-கரததன-தவறக-எடததக-களள-வணடம-அமசசர-ரஜமகன-1', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', '<p>சென்னை: அரசுப் பள்ளி மாணவிகளிடம் தொழில் துறை அமைச்சர் கீர்த்தனா ஆங்கிலத்தில் கேள்வி கேட்ட வீடியோ பெரும் சர்ச்சையை ஏற்படுத்தியுள்ளது. இந்நிலையில், அதுகுறித்து பள்ளிக் கல்வித் துறை அமைச்சர் ராஜ்மோகன் விளக்கம் அளித்துள்ளார். அமைச்சர் எந்தக் காணொளியையும் எடுக்கவில்லை என்றும், மாணவியிடம் அக்கா ஸ்தானத்தில் பேசியதை தவறாகப் புரிந்துகொள்ள வேண்டாம் என்றும் அவர் தெரிவித்துள்ளார்.<br><br>விருதுநகர் மாவட்டம், சிவகாசி அருகே திருத்தங்கலில் உள்ள அரசுப் பெண்கள் மேல்நிலைப் பள்ளியில் தொழில் துறை அமைச்சர் கீர்த்தனா ஆய்வு மேற்கொண்டார். அப்போது, வகுப்பறை ஒன்றுக்குள் சென்ற அமைச்சர் அங்குள்ள மாணவர்களிம் பேசினார். அப்போது, அங்கிருந்த மாணவிகளிடம் ஆங்கிலத்தில் அமைச்சர் சில கேள்விகளைக் கேட்டார். ஆங்கில கேள்விகளுக்கு பதிலளிக்க முடியாமல் மாணவிகள் சிலர் திணறினர்.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e25bc342c07.11789944.png', '', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 0, 1, 0, 1, 'published', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', 'அக்கா ஸ்தானத்தில் பேசிய கீர்த்தனா.. தவறாக எடுத்துக் கொள்ள வேண்டாம்.. அமைச்சர் ராஜ்மோகன்', '2026-07-08 10:25:35', '2026-07-08 15:55:35', '2026-07-08 15:56:30'),
(30, 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', 'பதவய-வடட-பஙக-தமழக-தரதல-ஆணயரகக-பரஷர-படம-மதலவர-வஜய-அரச-ஷக-பனனண', 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', '<p>சென்னை: தமிழகத்தில் அடுத்த ஆண்டு உள்ளாட்சி தேர்தல் நடைபெற வாய்ப்புள்ளது. இந்நிலையில் தான் உள்ளாட்சி தேர்தல்களை நடத்தும் தமிழ்நாடு தேர்தல் ஆணையர் பொறுப்பில் இருந்து விலக வேண்டும் என்று ஐஏஎஸ் அதிகாரி ஜோதி நிர்மலாசாமியிடம் முதல்வர் விஜய் தலைமையிலான தவெக அரசு கேட்டுள்ளதாக கூறப்படுகிறது. இந்த பொறுப்பில் ஜோதி நிர்மலாசாமியை முந்தைய திமுக அரசு நியமனம் செய்த நிலையில் அவரை மாற்றம் செய்யும் வகையில் தவெக அரசு பிரஷர் போடுவதாகவும், அதன் பின்னணி குறித்தும் பரபரப்பான தகவல்கள் வெளியாகி உள்ளது.<br><br>தமிழக தேர்தல் ஆணையராக ஜோதி நிர்மலாசாமி செயல்பட்டு வருகிறார். 2002ம் ஆண்டு பேட்ச்சை சேர்ந்த ஐஏஎஸ் அதிகாரியான இவர் கடந்த 2024ம் ஆண்டு மார்ச் மாதம் இந்த பொறுப்பில் நியமனம் செய்யப்பட்டார்.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e27f724d396.25293964.png', '', 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', 0, 1, 0, 1, 'published', 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', 'பதவியை விட்டு போங்க.. தமிழக தேர்தல் ஆணையருக்கு பிரஷர் போடும் முதல்வர் விஜய் அரசு.. ஷாக் பின்னணி', '2026-07-08 10:35:17', '2026-07-08 16:05:17', '2026-07-10 12:19:49'),
(31, 'இப்போ எலக்சன் வச்சாலும்.. விஜய் 180 சீட் ஜெயிப்பார்! கள நிலவரம் சொல்லுது! அடித்துச் சொல்லும் வைகோ!', 'இப்போ-எலக்சன்-வச்சாலும்-விஜய்-180-சீட்-ஜெயிப்பார்-கள-நிலவரம்-சொல்லுது-அடித்துச்-சொல்லும்-வைகோ-', 'இப்போ எலக்சன் வச்சாலும்.. விஜய் 180 சீட் ஜெயிப்பார்! கள நிலவரம் சொல்லுது! அடித்துச் சொல்லும் வைகோ!', '<p>தூத்துக்குடி: தமிழகத்தில் தலைவிரித்து ஆடிய கரெப்சன் என்ற மக்களுக்கு கேடான கொடிய நோய் ஒன்றை தமிழக வெற்றிக் கழகத்தில் தலைவரும் தமிழக முதலமைச்சருமான ஜோசப் விஜய் அதை நீக்கி இருக்கிறார் என்பதை யாரும் மறுக்க முடியாது எனவும், தமிழகத்தில் மீண்டும் ஒருமுறை தேர்தல் வந்தால் 180க்கும் மேற்பட்ட இடங்களை விஜய் அவர்கள் ஜெயித்து காட்டுவார் என மக்கள் மனநிலைப்பாடு. கள சூழலும் அப்படித்தான் உள்ளது என மதிமுக பொதுச் செயலாளர் வைகோ கூறியுள்ளார்.<br><br>சுற்றுச்சூழலுக்குப் பெரும் கேடு விளைவிக்கும் சீமை கருவேல மரங்களை தமிழ்நாட்டில் இருந்து வேரோடு அகற்றுவதில் மதிமுக பொதுச்செயலாளர் வைகோ நீண்ட காலமாகத் தீவிர சட்டப் போராட்டங்களை முன்னெடுத்து வருவதோடு, அம்மரங்களை தானே அகற்றும் வகையில் களப் பணிகளையும் மேற்கொண்டு வருகிறார்.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e29050a4ef0.62248651.png', '', 'இப்போ எலக்சன் வச்சாலும்.. விஜய் 180 சீட் ஜெயிப்பார்! கள நிலவரம் சொல்லுது! அடித்துச் சொல்லும் வைகோ!', 'இப்போ எலக்சன் வச்சாலும்.. விஜய் 180 சீட் ஜெயிப்பார்! கள நிலவரம் சொல்லுது! அடித்துச் சொல்லும் வைகோ!', 0, 1, 0, 1, 'published', 'இப்போ-எலக்சன்-வச்சாலும்-விஜய்-180-சீட்-ஜெயிப்பார்-கள-நிலவரம்-சொல்லுது-அடித்துச்-சொல்லும்-வைகோ-', 'இப்போ-எலக்சன்-வச்சாலும்-விஜய்-180-சீட்-ஜெயிப்பார்-கள-நிலவரம்-சொல்லுது-அடித்துச்-சொல்லும்-வைகோ-', 'இப்போ-எலக்சன்-வச்சாலும்-விஜய்-180-சீட்-ஜெயிப்பார்-கள-நிலவரம்-சொல்லுது-அடித்துச்-சொல்லும்-வைகோ-', '2026-07-08 10:39:50', '2026-07-08 16:09:50', '2026-07-10 12:19:49'),
(32, 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர்-கீர்த்தனாவை-நெருக்கும்-திமுக-தப்பாவே-தெரியலையா-மகளிரணி-ஐடி-விங்-பொறுப்பாளர்-பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', '<p>சென்னை: அரசுப் பள்ளியில் ஆய்வு என்ற பெயரில் ரீல்ஸ் வெளியிட்டு மாணவியை தொழில்துறை அமைச்சர் கீர்த்தனா அவமதித்து உள்ளதாக குற்றம்சாட்டியுள்ள திமுக மகளிரணி சமூக வலைதளப் பொறுப்பாளர் மரு.யாழினி செய்தியாளர்களிடம் விரிவாக விவரித்தார். அப்போது அவர் கூறுகையில், \"அமைச்சர் கீர்த்தனா செய்தது எமோஷனல் அப்யூஸ் &amp; துன்புறுத்தல். சமூக புரிதலில்லாமல் குழந்தைகளிடம் அராஜகம் விக்டிம் கார்டு பிளே பண்ணாதீங்க, அந்த இடத்தில் அந்தக் குழந்தை தான் விக்டிம்.<br><br>தவெக கட்சி ஆட்சிக்கு வருவதற்கு முன்பு தங்களின் பிரச்சாரத்திற்கு குழந்தைகளைப் பயன்படுத்தி பெற்றோர்களைப் பிளாக் மெயில் செய்து வாக்களிக்க வைத்தனர். தற்போதும் தாங்கள் செய்யும் குற்றங்களை மறைக்க குழந்தைகளைக் கேடயமாக பயன்படுத்தி வருகின்றனர். சமீபத்தில் தவெக அமைச்சர் சரத்குமார் அவர்கள் போதை பொருளை பயன்படுத்தியது போல ஒரு வீடியோ வெளியானது எதிர்ப்பு கிளம்பியதும் உடனடியாக அவரது குழந்தையை கேடயமாக்கி அதில் இருந்து தப்பித்துக்கொள்ளப் பார்க்கிறார். நிறைய தவெக நிர்வாகிகள் தொடர்ச்சியாக குழந்தைகளை இது போன்று எமோஷனலா அப்யூஸ் பண்ணிட்டு இருக்காங்க. இது மிகவும் கண்டிக்கத்தக்கது.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e2a60ed4b62.62523617.png', '', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டிசென்னை: அரசுப் பள்ளியில் ஆய்வு என்ற பெயரில் ரீல்ஸ் வெளியிட்டு மாணவியை தொழில்துறை அமைச்சர் கீர்த்தனா அவமதித்து உள்ளதாக குற்றம்சாட்டியுள்ள திமுக மகளிரணி சமூக வலை', 0, 1, 0, 0, 'trash', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', '2026-07-08 10:45:40', '2026-07-08 16:15:40', '2026-07-10 12:19:49'),
(33, 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர்-கீர்த்தனாவை-நெருக்கும்-திமுக-தப்பாவே-தெரியலையா-மகளிரணி-ஐடி-விங்-பொறுப்பாளர்-பேட்டி-', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', '<p>சென்னை: அரசுப் பள்ளியில் ஆய்வு என்ற பெயரில் ரீல்ஸ் வெளியிட்டு மாணவியை தொழில்துறை அமைச்சர் கீர்த்தனா அவமதித்து உள்ளதாக குற்றம்சாட்டியுள்ள திமுக மகளிரணி சமூக வலைதளப் பொறுப்பாளர் மரு.யாழினி செய்தியாளர்களிடம் விரிவாக விவரித்தார். அப்போது அவர் கூறுகையில், \"அமைச்சர் கீர்த்தனா செய்தது எமோஷனல் அப்யூஸ் &amp; துன்புறுத்தல். சமூக புரிதலில்லாமல் குழந்தைகளிடம் அராஜகம் விக்டிம் கார்டு பிளே பண்ணாதீங்க, அந்த இடத்தில் அந்தக் குழந்தை தான் விக்டிம்.<br><br>தவெக கட்சி ஆட்சிக்கு வருவதற்கு முன்பு தங்களின் பிரச்சாரத்திற்கு குழந்தைகளைப் பயன்படுத்தி பெற்றோர்களைப் பிளாக் மெயில் செய்து வாக்களிக்க வைத்தனர். தற்போதும் தாங்கள் செய்யும் குற்றங்களை மறைக்க குழந்தைகளைக் கேடயமாக பயன்படுத்தி வருகின்றனர். சமீபத்தில் தவெக அமைச்சர் சரத்குமார் அவர்கள் போதை பொருளை பயன்படுத்தியது போல ஒரு வீடியோ வெளியானது எதிர்ப்பு கிளம்பியதும் உடனடியாக அவரது குழந்தையை கேடயமாக்கி அதில் இருந்து தப்பித்துக்கொள்ளப் பார்க்கிறார். நிறைய தவெக நிர்வாகிகள் தொடர்ச்சியாக குழந்தைகளை இது போன்று எமோஷனலா அப்யூஸ் பண்ணிட்டு இருக்காங்க. இது மிகவும் கண்டிக்கத்தக்கது.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e2aee6e7e96.90334882.png', '', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 0, 1, 0, 1, 'published', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', 'அமைச்சர் கீர்த்தனாவை நெருக்கும் திமுக.. தப்பாவே தெரியலையா... மகளிரணி ஐடி விங் பொறுப்பாளர் பேட்டி', '2026-07-08 10:47:57', '2026-07-08 16:17:57', '2026-07-10 12:19:49'),
(34, 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', 'சநதல-பலஜ-மனஜமன-வழககல-தமழக-அரச-அதரட-பறபகலல-ஆஜரகம-அரசன-மதத-வழககறஞர', 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', '<p>சென்னை: திமுக முன்னாள் அமைச்சர் செந்தில் பாலாஜி மற்றும் அவரது சகோதரர் அசோக்குமார் ஆகியோரின் முன்ஜாமீன் மனுக்கள் இன்று பிற்பகல் 3.30 மணிக்கு விசாரணைக்கு வர உள்ளது. இன்று காலை விசாரணைக்கு வந்த போது, தமிழக அரசின் மூத்த வழக்கறிஞர் ஆஜராக உள்ளதால், பிற்பகலுக்கு வழக்கை தள்ளிவைக்க வேண்டும் என்று அரசு தரப்பு வாதிட்டது. இதனை ஏற்று வழக்கை பிற்பகலுக்கு நீதிமன்றம் தள்ளிவைத்துள்ளது.<br><br>முதல்வர் விஜய் தலைமையிலான த.வெ.க. ஆட்சியை கவிழ்ப்பதற்கு, சதித்திட்டம் தீட்டி கிருஷ்ணகிரி மாவட்டம் ஊத்தங்கரை தொகுதி த.வெ.க. எம்.எல்.ஏ. டாக்டர் இளையராஜாவிடம் ரூ.35 கோடி தருவதாக பேரம் பேசியதாக குற்றச்சாட்டு எழுந்தது. இந்த விவகாரம் தொடர்பாக சென்னை மாநகர போலீஸ் கமிஷனர் அலுவலகத்தில் இளையராஜா புகார் மனு ஒன்றை கொடுத்தார். அந்த புகாரின் அடிப்படையில் சென்னை திருவல்லிக்கேணி போலீசார் வழக்குப்பதிவு செய்து விசாரித்தனர்.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e2c9e5f9814.74616048.png', '', 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', 0, 1, 0, 1, 'published', 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', 'செந்தில் பாலாஜி முன்ஜாமீன் வழக்கில் தமிழக அரசு அதிரடி... பிற்பகலில் ஆஜராகும் அரசின் மூத்த வழக்கறிஞர்', '2026-07-08 10:55:14', '2026-07-08 16:25:14', '2026-07-10 12:19:49'),
(35, 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', 'கரர-கடட-நரசல-அரச-வலகக-எதரக-நதக-நரவக-மனஅவசர-வசரணகக-உயரநதமனறம-மறபப', 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', '<p>மதுரை: கரூர் கூட்ட நெரிசலில் சிக்கி உயிரிழந்தோரின் குடும்பத்தினருக்கு அரசு வேலை வழங்க தமிழக அரசு எடுத்துள்ள முடிவுக்கு எதிர்ப்புத் தெரிவித்து, நாம் தமிழர் கட்சி நிர்வாகி தாக்கல் செய்த மனுவை அவசர வழக்காக விசாரிக்க உயர்நீதிமன்ற மதுரை அமர்வு மறுப்பு தெரிவித்துள்ளது.<br><br>தவெக கட்சி தொடங்கியதில் இருந்து பல்வேறு சர்ச்சைகள் எழுந்து வருகின்றன. அதில் முக்கியமானது கரூர் சம்பவம். கடந்த ஆண்டு செப்டம்பர் 27 ஆம் தேதி தேர்தல் பிரச்சாரத்திற்காக தவெக தலைவர் விஜய் கரூர் மாவட்டம் வேலுசாமிபுரம் சென்றிருந்தார். விஜயைக் காண்பதற்காக அதிகளவு மக்கள் கூடியிருந்தனர். அப்போது கரூரில் எதிர்பாராதவிதமாக நெரிசல் ஏற்பட்டது. இந்த நெரிசலில் சிக்கி 41 மக்கள் பரிதாபமாக உயிரிழந்தனர். மேலும் பலர் காயமடைந்தனர்.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e2dd65f53e9.44695495.png', '', 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', 0, 1, 0, 0, 'published', 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', 'கரூர் கூட்ட நெரிசல்: அரசு வேலைக்கு எதிராக நாதக நிர்வாகி மனு..அவசர விசாரணைக்கு உயர்நீதிமன்றம் மறுப்பு', '2026-07-08 11:00:27', '2026-07-08 16:30:27', '2026-07-10 12:19:49'),
(36, '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', 'சமக-நதததற-எனபத-நககதத-சதககம-ஒரபதம-ஏறக-மடயத-ஜகன-மரதத-எதரபப', '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', '<p>சென்னை: தமிழ்நாடு அரசின் ஆதிதிராவிடர் மற்றும் பழங்குடியினர் நலத்துறை \'சமூக நீதித்துறை\' என மாற்றம் செய்து தமிழ்நாடு அரசின் தலைமைச் செயலாளர் சாய்குமார் அரசாணை வெளியிட்டுள்ளார். அரசு ஆவணங்கள் மற்றும் கோப்புகளில் பெயர் மாற்றம் செய்யும் வகையில், தமிழ்நாடு வணிக விதிகளில் திருத்தம் செய்து நடவடிக்கை எடுக்கப்பட்டிருக்கிறது. இதற்கு பூஜை ஜெகன் மூர்த்தி கடும் எதிர்ப்பு தெரிவித்துள்ளார்.<br><br>தமிழ்நாடு அரசில் ஆதிதிராவிடர் மற்றும் பழங்குடியினர் நலத்துறை இயங்கி வருகிறது. இந்த துறை பட்டிய இனத்தவர் மற்றும் பழங்குடி சமூகத்தினரின் கல்வி, பொருளாதாரம் மற்றும் சமூக மேம்பாட்டிற்காக பல்வேறு திட்டங்களை ஆய்வு செய்து செயல்படுத்துகிறது. குறிப்பாக பள்ளி-கல்லூரி மாணவர்களுக்கான கல்வி உதவித்தொகை, இலவச விடுதிகள், திறன் மேம்பாட்டுப் பயிற்சி, வீட்டுமனைப் பட்டா வழங்குதல் போன்ற பல்வேறு பணிகளை முன்னெடுத்து செயல்படுத்துகிறது.<br><br><br></p>', 4, 11, 1, 'uploads/news/jp_6a4e340bb20914.96008822.png', '', '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', 0, 1, 0, 1, 'published', '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', '\'சமூக நீதித்துறை\' என்பது நோக்கத்தை சிதைக்கும்.. ஒருபோதும் ஏற்க முடியாது.. ஜெகன் மூர்த்தி எதிர்ப்பு', '2026-07-08 11:26:51', '2026-07-08 16:56:51', '2026-07-10 12:19:49'),
(37, 'கரூருக்கு போவதற்குள் கைது செய்ய நினைத்த விஜய்! பக்காவாக தப்பித்த செந்தில் பாலாஜி! விஜய் செம அப்செட்', 'கரரகக-பவதறகள-கத-சயய-நனதத-வஜய-பககவக-தபபதத-சநதல-பலஜ-வஜய-சம-அபசட', 'கரூருக்கு-போவதற்குள்-கைது-செய்ய-நினைத்த-விஜய்-பக்காவாக-தப்பித்த-செந்தில்-பாலாஜி-விஜய்-செம-அப்செட்-', '<p>சென்னை: ₹35 கோடி குதிரை பேர விவகாரம் தொடர்பான வழக்கில் செந்தில் பாலாஜிக்கு நேற்று ஜாமீன் வழங்கப்பட்டது. மாஜி அமைச்சர் செந்தில் பாலாஜி ஜாமீன் பெற்றது தற்போது முதல்வர் விஜய்க்கு சிக்கலாக முடிந்துள்ளது.<br><br>தவெக ஊத்தங்கரை எம்.எல்.ஏ இளையராஜாவை விலைக்கு வாங்க முயன்ற வழக்கில், திமுக முன்னாள் அமைச்சர் வி. செந்தில்பாலாஜி மற்றும் அவரது சகோதரர் ஆர்.வி. அசோக் குமார் ஆகியோருக்கு சென்னை உயர் நீதிமன்றம் முன்ஜாமீன் வழங்கிய விவகாரம், தவெக வட்டாரத்தில் பெரும் அதிர்ச்சியை ஏற்படுத்தியுள்ளது.<br>குறிப்பாக, இந்த தீர்ப்பின் பின்னணியில் தவெக தலைவர் முதல்வர் விஜய் கடும் அப்செட்டில் இருப்பதாக விபரமறிந்த வட்டாரங்கள் தெரிவிக்கின்றன. கரூரில் அரங்கேறவிருந்த கைது வியூகம் முதல்வர் விஜய் நாளை கரூர் மாவட்டத்திற்கு மிக முக்கியமான அரசியல் பயணமொன்றை மேற்கொள்ளத் திட்டமிட்டிருந்தார். அங்கு அவருக்கு பிரம்மாண்ட வரவேற்பு அளிக்க தவெக தரப்பு தயாராகி வந்தது. விஜய் கரூர் மண்ணில் கால் வைப்பதற்கு முன்பாகவே, செந்தில் பாலாஜியை கைது செய்ய வேண்டும் என்பதே விஜய்யின் திட்டமாக இருந்தது. இந்த ₹35 கோடி லஞ்சப் புகாரில் அவரை அதிரடியாகக் கைது செய்ய திட்டமிட்டிருந்ததாகக் கூறப்படுகிறது. சபாநாயகர் ஜே.சி.டி. பிரபாகரனுக்கு எதிராக தீர்மானம் கொண்டு வர முயன்றது மற்றும் தவெக அரசை கலைக்க சதித் திட்டம் தீட்டியது ஆகிய கடுமையான குற்றச்சாட்டுகளின் கீழ் இந்த கைது நடவடிக்கையை அரங்கேற்ற காய் நகர்த்தப்பட்டது.<br><br><br></p>', 1, 2, 1, 'uploads/news/jp_6a4f1e405d2c63.87115360.png', '', 'கரூருக்கு-போவதற்குள்-கைது-செய்ய-நினைத்த-விஜய்-பக்காவாக-தப்பித்த-செந்தில்-பாலாஜி-விஜய்-செம-அப்செட்-', 'கரூருக்கு-போவதற்குள்-கைது-செய்ய-நினைத்த-விஜய்-பக்காவாக-தப்பித்த-செந்தில்-பாலாஜி-விஜய்-செம-அப்செட்-', 0, 1, 0, 1, 'published', 'கரூருக்கு-போவதற்குள்-கைது-செய்ய-நினைத்த-விஜய்-பக்காவாக-தப்பித்த-செந்தில்-பாலாஜி-விஜய்-செம-அப்செட்-', 'கரூருக்கு-போவதற்குள்-கைது-செய்ய-நினைத்த-விஜய்-பக்காவாக-தப்பித்த-செந்தில்-பாலாஜி-விஜய்-செம-அப்செட்-', 'கரூருக்கு-போவதற்குள்-கைது-செய்ய-நினைத்த-விஜய்-பக்காவாக-தப்பித்த-செந்தில்-பாலாஜி-விஜய்-செம-அப்செட்-', '2026-07-09 04:06:24', '2026-07-09 09:33:53', '2026-07-10 12:19:49'),
(38, 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', 'நரககட-கடககம-பதசசர-நதமனறம-உயரநதமனறததல-அமசசர-மரய-வலசன-அவசர-மன', 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', '<p>சென்னை: தனது சகோதரர் தன் மீது தொடுத்துள்ள கொலை முயற்சி வழக்கை ரத்து செய்ய கோரி, அமைச்சர் மரிய வில்சன் சென்னை உயர்நீதிமன்றத்தில் மனுத்தாக்கல் செய்திருக்கிறார். இந்த மனு இன்று விசாரணைக்கு வருகிறது.<br>ஏற்கெனவே இந்த வழக்கில், மரிய வில்சன் ஆஜராக வேண்டும் என்று புதுச்சேரி நீதிமன்றம் உத்தரவிட்டிருந்தது. ஆனால், அவர் ஆஜராகவில்லை. இப்படி இருக்கையில் தற்போது உயர்நீதிமன்றத்தை நாடியுள்ளார்.<br><br>வழக்கின் பின்னணி அமைச்சர் மரிய வில்சனுக்கும், அவரது அண்ணன் மரிய குலோத்துக்கும் நீண்ட நாட்களாக சொத்து பிரச்சனை நீடித்து வருகிறது. இப்படி இருக்கையில், கடந்த 2022ம் ஆண்டு புதுச்சேரியில் உள்ள அவரது அண்ணன் வீட்டில் அத்துமீறி நுழைந்து தாக்குதல் நடத்தியதாக அமைச்சர் மரிய வில்சன் மீது குற்றச்சாட்டு எழுந்தது. இது தொடர்பாக புதுச்சேரி போலீசார் 6 பிரிவுகளின் கீழ் வழக்குப்பதிவு செய்திருந்தனர். வீடியோ ஆதாரம் ஆனால், மரிய வில்சன் மீது எளிதில் ஜாமீனில் வெளிவரக்கூடிய பிரிவுகளில்தான் காவல்துறையினர் வழக்குப்பதிவு செய்திருப்பதாகவும், கடுமையான சட்டப்பிரிவுகளின் கீழ் வழக்கு பதிவு செய்யப்பட வேண்டும் என்று கேட்டு.. தாக்குதலுக்கு உள்ளானவர்கள் நீதிமன்றத்தை அணுகி, வீடியோ ஆதாரத்தை சமர்ப்பித்தனர். இந்த வீடியோ சோஷியல் மீடியாக்களில் வெளியாகி மரிய வில்சனுக்கு எதிராக திரும்பியது. பின்னர் நீதிமன்றத்தின் உத்தரவை தொடர்ந்து.. வீடியோ ஆதாரத்தின் அடிப்படையில் கடுமையான பிரிவுகளின் கீழ் வழக்கு மாற்றப்பட்டது.<br><br></p>', 1, 6, 1, 'uploads/news/jp_6a4f25a0983165.44076469.png', '', 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', 0, 1, 0, 0, 'published', 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', 'நெருக்கடி கொடுக்கும் புதுச்சேரி நீதிமன்றம்.. உயர்நீதிமன்றத்தில் அமைச்சர் மரிய வில்சன் அவசர மனு!', '2026-07-09 04:37:52', '2026-07-09 10:07:52', '2026-07-10 12:19:49'),
(39, 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', 'கிண்டலுக்கு-உள்ளாகும்-திருமாவளவன்-பேச்சு-ஊடகங்கள்-திரித்து-பரப்புவதாக-விளக்கம்', 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', '<p>அரியலூர்: தவெக அமைச்சரவையில் விசிக பங்கேற்று இருந்தாலும், திமுக தலைவர் ஸ்டாலினுடன் கருத்து பங்கேற்பு தொடர்ந்து கொண்டே இருக்கும், தவிர்க்க மாட்டேன் என திருமாவளவன் பேசியதை இது நோபல் பரிசு கொடுக்கப்பட வேண்டிய கருத்து என்று கிண்டலாக கூறியிருந்தார். இதேபோல் தவெக அமைச்சரவையில் உள்ள திருமாவளவனின் விசிக, திமுக கூட்டணியுடன் நட்புடன் உள்ளதாக கூறுவதை பலரும் கிண்டல் செய்கிறார்கள். ஊடகங்களும் திருமாவளவனை சராமரியாக கிண்டல் செய்கிறது. இதற்கு பதில் அளித்துள்ள திருமாவளவன் நான் சொல்கிற கருத்தை ஊடகங்கள் திரித்து பரப்புவதாக நினைக்கிறேன் என்று கூறினார்.<br><br>அரியலூர் மாவட்ட ஆட்சியர் கூட்டரங்கில் மாவட்ட வளர்ச்சி மற்றும் கண்காணிப்பு குழு கூட்டம் அக்குழு தலைவரும் சிதம்பரம் நாடாளுமன்ற உறுப்பினர் திருமாவளவன் தலைமையில் நடந்தது. இக்கூட்டத்தில் அனைத்து துறை அரசு உயர் அதிகாரிகள் கலந்து கொண்டு அவரவர்களின் துறைகளில் மேற்கொள்ளப்பட்டு வரும் வளர்ச்சி திட்ட பணிகள் குறித்து விளக்கினர். இக்கூட்டத்தில் மாவட்ட ஆட்சியர் மிருணாளினி உள்ளிட்ட அனைத்து துறை அரசு உயர் அதிகாரிகள் கலந்து கொண்டனர்.<br><br>திருமாவளவன் செய்தியாளர் சந்திப்பு பின்னர் செய்தியாளர்களை சிதம்பரம் நாடாளுமன்ற உறுப்பினரும் விடுதலை சிறுத்தை கட்சி தலைவர் தொல் திருமாவளவன் சந்தித்தார். அப்பொழுது அவர் பேசுகையில், \"தற்பொழுது உள்ள புதிய 100 நாள் வேலைவாய்ப்பு திட்டத்திற்கு நாடாளுமன்றத்திலேயே நாங்கள் எதிர்ப்பு தெரிவித்தோம். மகாத்மா காந்தி பெயரில் இருந்த இந்த திட்டத்தை மகாத்மா காந்தி பெயரை நீக்கிவிட்டு புதிய பெயரில் அறிவித்துள்ளார்கள். இது காந்தியடிகளின் மீதான வெறுப்பை உமிழ்வது போல் உள்ளது. 125 நாள் என்று உயர்த்தி இருப்பதாக சொல்கிறார்கள். ஆனால் தேவையான அளவிற்கு போதுமான நிதியை ஒதுக்க தயங்குகிறார்கள், மறுக்கிறார்கள். ஒட்டுமொத்தமாக 100 நாள் வேலை வாய்ப்பு திட்டத்தை ஒழிக்க வேண்டும் என்பதுதான் பாஜக எண்ணம். ஆனால் வெளியில் ஒரு மாதிரி பேசுகிறார்கள்.. நிதியை ஒதுக்கீடு செய்வதில் வஞ்சகமாக செயல்படுகிறார்கள். இது எல்லாம் நாடாளுமன்ற அவையிலே நாங்கள் சுட்டிக் காட்டியுள்ளோம். கண்டித்து உள்ளோம். இதனால் இத்திட்டத்தில் மாநில அரசு பங்கேற்க வேண்டும் என்ற நடைமுறை ஏற்புடையதாக இல்லை. இதை நாங்கள் தொடர்ந்து எதிர்ப்போம்.<br><br></p>', 1, 11, 1, 'uploads/news/jp_6a4f28b008e7f1.69126292.png', '', 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', 0, 1, 0, 0, 'published', 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', 'கிண்டலுக்கு உள்ளாகும் திருமாவளவன் பேச்சு.. ஊடகங்கள் திரித்து பரப்புவதாக விளக்கம்', '2026-07-09 04:50:56', '2026-07-09 10:20:56', '2026-07-10 12:19:49'),
(40, 'தவெகவுக்கு அடுத்தடுத்து சரிவு.. அடித்து ஆடிய திமுக! விஜய் நெனைச்சது நடக்கலையே!', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', '<p>சென்னை: நீதிமன்ற விஷயத்தில் தவெக நினைத்து முழுமையாக நடக்காததால் முதலமைச்சர் விஜய் அப்செட்டில் இருப்பதாக தகவல்கள் வெளியாகியுள்ளன. குறிப்பாக செந்தில் பாலாஜிக்கு ஜாமீன் கிடைத்த விஷயத்தை தவெக கொஞ்சம் கூட எதிர்பார்க்கவில்லை.<br><br>சமீபத்தில் உச்சநீதிமன்றத்தில், கரூர் தொடர்பான வழக்கில் தவெக வெற்றி பெற்றிருந்தது. இதே உற்சாகத்தோடு மற்ற வழக்குகளில் நுழைந்த தவெகவுக்கு பெரிய ஏமாற்றம்தான் மிஞ்சியிருந்தது.<br><br>அனிதா ராதாகிருஷ்ணன் வழக்கு கடந்த ஜூன் மாதம் தூத்துக்குடி ஆத்தூரில் நடைபெற்ற பொதுக்கூட்டத்தில் பங்கேற்று பேசியிருந்த முன்னாள் அமைச்சர் அனிதா ராதாகிருஷ்ணன், முதலமைச்சர் விஜய் குறித்து அவதூறாக பேசியதாக குற்றச்சாட்டுக்கு உள்ளார். அவர் மீது வழக்கு பதிவு செய்யப்பட்டிருந்தது. இருப்பினும் முன்ஜாமீன் கோரி அவர் நீதிமன்றத்தை அணுகியிருந்தார். ஆனால், சென்னை உயர்நீதிமன்றம் அவரது ஜாமீன் மனுவை தள்ளுபடி செய்திருந்தது. ஜாமீன் வழங்கிய நீதிமன்றம் ஜாமீன் தள்ளுபடி செய்யப்பட்ட 90 நிமிடங்களில், அதாவது ஒன்றரை மணி நேரத்தில் அவர் கைது செய்யப்பட்டார். மேலும், அவர் தனது சொந்த காரில் காவல் நிலையத்திற்கு வர அனுமதிக்கப்படவில்லை. மாறாக காவல்துறையின் ஜீப்பில் காவல் நிலையம் அழைத்து வரப்பட்டார். 6 மணி நேர விசாரணைக்கு பின்னர், அவர் திருச்செந்தூர் குற்றவியல் நீதித்துறை நடுவர் முன்பு ஆஜர்படுத்தப்பட்டபோது, நிபந்தனை ஜாமீன் வழங்கி நீதிபதி உத்தரவிட்டார்.<br><br><br></p>', 1, 11, 1, 'uploads/news/jp_6a4f2a0c1745a2.63181050.png', '', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', 0, 1, 0, 0, 'published', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', 'தவெகவுக்கு-அடுத்தடுத்து-சரிவு-அடித்து-ஆடிய-திமுக-விஜய்-நெனைச்சது-நடக்கலையே-', '2026-07-09 04:56:44', '2026-07-09 10:26:44', '2026-07-10 12:19:49'),
(41, 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', 'செங்கல்பட்டு-சென்னை-கடற்கரை-வழித்தடத்தில்-3-நாட்கள்-மின்சார-ரயில்கள்-ரத்து-', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', '<p>சென்னை: சென்னை கடற்கரை மற்றும் செங்கல்பட்டு இடையே கூடுவஞ்சேரி யார்டில் அவசியமான பராமரிப்பு பணிகள் காரணமாக இன்று 8 புறநகர் ரயில் சேவை ரத்து செய்யப்பட்டுள்ளது. ஜூலை 13, 15ஆம் தேதிகளிலும் சென்னை கடற்கரை - செங்கல்பட்டு இடையே 8 புறநகர் ரயில் சேவை ரத்து செய்யப்பட்டுள்ளது. மதியம் 1.40 மணி முதல் மாலை 5.40 மணி வரையிலான 4 மணி நேர கால அளவில், சென்னை கடற்கரை - செங்கல்பட்டு இடையே இரு மார்க்கங்களிலும் இயக்கப்படும் 8 புறநகர் ரயில் சேவைகள் முழுமையாக ரத்து செய்யப்படுவதாக அறிவிக்கப்பட்டுள்ளது.<br>சென்னை புறநகர் மக்களுக்கு மின்சார ரயில்கள் தான் முக்கியமான போக்குவரத்து வசதியாகும். ஆனால் அடிக்கடி பராமரிப்பு பணிகள் காரணமாக செங்கல்பட்டு முதல் தாம்பரம் இடையே மின்சார ரயில்கள் பகுதி நேரமாக ரத்து செய்யப்படுவது தொடர்கதையாக உள்ளது. கடந்த ஞாயிற்றுக்கிழமை இதே வழித்தடத்தில் பராமரிப்பு பணி காரணமாக, காலை 10.30 மணி முதல் மதியம் 3.30 மணி வரை 41 புறநகர் ரயில்கள் ரத்து அடியோடு செய்யப்பட்டிருந்தன.<br><br>இதனால் பயணிகள் கடும் அவதி அடைந்தனர். ரயில்வே பராமரிப்பு பணிகள் அவசியம் தான் என்றாலும், பொதுமக்களை பாதிக்காத வகையில் பணிகளை மேற்கொள்ள வேண்டும் என்று கோரிக்கை வைத்து வந்தனர். இந்த சூழலில் மதிய நேரங்களில் கூடுவஞ்சேரி யார்டில் பராமரிப்பு பணிகள் மேற்கொள்ள முடிவு செய்யப்பட்டுள்ளது. இதற்காக இன்று மதியம் முதல் மாலை வரை மின்சார ரரயில்கள் ரத்து செய்யப்பட்டுள்ளது. இன்று 8 புறநகர் ரயில் சேவை ரத்து செய்யப்பட்டுள்ளது. ஜூலை 13, 15ஆம் தேதிகளிலும் இதே மின்சார ரயில்கள் ரத்து செய்யப்படுகின்றன.<br><br>தெற்கு ரயில்வே வெளியிட்டுள்ள அறிவிப்பின் படி, சென்னை கடற்கரை ரயில் நிலையத்திலிருந்து செங்கல்பட்டு செல்லும் மின்சார ரயில்களில், காலை 11.28 மணி, மதியம் 12.02 மணி, மதியம் 12.30 மணி மற்றும் மதியம் 1.45 மணிக்கு புறப்பட வேண்டிய 4 புறநகர் ரயில்கள் முழுமையாக ரத்து செய்யப்பட்டுள்ளன. அதேபோல், மறுமார்க்கத்தில் செங்கல்பட்டு ரயில் நிலையத்திலிருந்து சென்னை கடற்கரை சந்திப்புக்கு வரும் ரயில்கள் மதியம் 1.35 மணி, மதியம் 2.15 மணி, மதியம் 3.00 மணி மற்றும் மாலை 4.25 மணிக்கு புறப்பட வேண்டிய 4 புறநகர் ரயில்களும் முழுமையாக ரத்து செய்யப்படுகிறது.<br><br></p>', 1, 11, 1, 'uploads/news/jp_6a4f2ae926ed28.58843671.png', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', 0, 1, 0, 0, 'published', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', 'செங்கல்பட்டு- சென்னை கடற்கரை வழித்தடத்தில் 3 நாட்கள் மின்சார ரயில்கள் ரத்து', '2026-07-09 05:00:25', '2026-07-09 10:30:25', '2026-07-10 12:19:49'),
(42, 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', 'பல்லாவரம்-குன்றத்தூர்-சாலை-ஆக்கிரமிப்புகளால்-மாறாத-காட்சி-பொதுமக்கள்-கோரிக்கை-', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', '<p>சென்னை: சென்னையின் புறநகர் பகுதிகளை இணைக்கும் பல்லாவரம்-குன்றத்தூர் சாலையை நான்கு வழிச்சாலையாக மாற்ற திட்டமிட்டு பணிகள் நடந்து வருகிறது. ஆனால் சாலை விரிவாக்க பணிகள் தொடங்கி 7 மாதங்கள் ஆகியும், இன்னும் ஒரு சில இடங்களில் வருவாய்த்துறை அதிகாரிகள் ஆக்கிரமிப்புகளை அகற்றாமலும், மின்வாரிய துறை அதிகாரிகள் மின்கம்பங்களை அகற்றாமலும் இருக்கிறது. இதனால் பணிகளில் பெரிய தொய்வு ஏற்பட்டுள்ளதாக பொதுமக்கள் குற்றம்சாட்டுகிறார்கள்.<br><br>பல்லாவரம்-குன்றத்தூர் சாலை வழியாகவே பலர் சென்னை வெளிவட்டச்சாலை செல்ல பயன்படுத்துகிறார்கள். அதேபோல் அனகாபுத்தூர், குன்றத்தூர், போரூர், பூந்தமல்லி, ஆவடி செல்வதற்கு இந்த சாலையை பலர் தினந்தோறும் பயன்படுத்துகிறார்கள். அதேபோல் குன்றத்தூரில் இருந்து சென்னை விமான நிலையம், தாம்பரம் உள்ளிட்ட பல்வேறு பகுதிகளுக்கு செல்வதற்கு இந்த சாலை தான் பிரதான சாலையாகும். இந்த சாலை மிக குறுகலாக உள்ளது. இதனால் எப்போதுமே கடும் போக்குவரத்து நெரிசல் ஏற்பட்டு வந்தது. இதனை தவிர்க்கும் விதமாக கடந்த தி.மு.க. ஆட்சி காலத்தில் பல்லாவரம் - குன்றத்தூர் சாலையை நான்கு வழி சாலையாக விரிவாக்கம் செய்ய முடிவு செய்யப்பட்டது.<br><br>கடந்த ஆண்டு குன்றத்தூர் அடுத்த கரைமாநகர் பகுதியில் இருந்து குன்றத்தூர் வரை நான்கு வழி சாலையாக மாற்றுவதற்கு சாலையோரத்திலிருந்த ஆக்கிரமிப்புகள் அகற்றப்பட்டது. அத்துடன் அவர்களுக்கு மாற்று இடம் வழங்கப்பட்டது. மேலும் கரைமாநகர் பகுதியில் புதிய பாலம் அமைத்து சாலை விரிவாக்கம் செய்வதற்காக ரூ.12 கோடி நிதி ஒதுக்கீடு செய்யப்பட்டது. அதன்படி அந்த பகுதியில் இருந்த பழைய தரைப்பாலம் இடிக்கப்பட்டு புதிய பாலம் அமைப்பதற்கான பணிகள் நடந்து வருகிறது. ஆனால் பல்லவாரம் குன்றத்தூர் சாலை பணிகளை பொறுத்தவரை 7 மாதங்கள் ஆகியும், இன்னும் ஒரு சில இடங்களில் ஆக்கிரமிப்புகள் அகற்றப்படாமல் உள்ளது. அதேபோல் மின்வாரிய துறை அதிகாரிகள் மின்கம்பங்களை அகற்றாமல் உள்ளனர். இதனால் சாலை விரிவாக்க பணி கிடப்பில் போடப்பட்டுள்ளது. ஆக்கிரமிப்பு செய்தவர்கள் நிலம் தொடர்பாக கோர்ட்டில் வழக்கு தொடர்ந்து உள்ளார்கள். அதுவும் பணிகள் தொய்வடைய காரணமாக உள்ளது.<br><br></p>', 1, 11, 1, 'uploads/news/jp_6a4f2d0c52f6f6.79745773.png', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', 0, 1, 0, 0, 'published', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', 'பல்லாவரம் - குன்றத்தூர் சாலை.. ஆக்கிரமிப்புகளால் மாறாத காட்சி.. பொதுமக்கள் கோரிக்கை', '2026-07-09 05:09:32', '2026-07-09 10:39:32', '2026-07-10 12:19:49'),
(43, 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', 'டீ-காபி-விலை-எகிற-போகுது-பால்-விலை-உயர்வு-தமிழகம்-முழுவதும்-அமலுக்கு-வருகிறது-புது-ரேட்-', 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', '<p>சென்னை: தமிழகம் முழுவதும் தனியார் பால் விற்பனை நிறுவனமான ஆரோக்யா, விலையை உயர்த்தியுள்ளது. இதனால் மற்ற நிறுவனங்களும் விலையை ஏற்ற இருப்பதாக தகவல்கள் வெளியாகியுள்ளன. இதனால் இனி டீ, காபி ரேட்டும் அதிகரிக்கும்.<br>பால் கொள்முதல் விலை மற்றும், அதை விநியோக்க ஆகும் செலவு காரணமாக இந்த விலையுயர்வு அமலுக்கு வருவதாக தெரிவிக்கப்பட்டிருக்கிறது. பெட்ரோல், டீசல் விலை உயர்வும் பால் விலை உயர்வுக்கு முக்கிய காரணமாக சொல்லப்படுகிறது.<br>சமன்படுத்தப்பட்ட பால் 500 மி.லி - ரூ.29லிருந்து, ரூ.31ஆகவும் நிலப்படுத்தப்பட்ட பால் 500 மி.லி - ரூ.35லிருந்து, ரூ.37ஆகவும் கொழுப்பு சத்து செறிவூட்டப்பட்ட பால் 500 மி.லி - ரூ.39லிருந்து, ரூ.41ஆகவும் சமன்படுத்தப்பட்ட பால் 1 லி - ரூ.66லிருந்து, ரூ.69ஆகவும் கொழுப்பு சத்து செறிவூட்டப்பட்ட பால் 1 லி - ரூ.73லிருந்து, ரூ.76ஆகவும் என புதிய விலையில் இன்று முதல் பால் விற்பனை செய்யப்படுகிறது. இந்த விலை உயர்வு அனைத்து தரப்பு மக்களையும் கடுமையாக பாதிக்கும் என சமூக ஆர்வலர்கள் எச்சரித்துள்ளனர். இதனை சரி செய்ய வேண்டும் எனில், ஆவின் பால் விற்பனையை தமிழகம் முழுவதும் விரிவுப்படுத்த வேண்டும். இன்னும் கிராமங்களில் ஆவின் பாலுக்கு தட்டுப்பாடு நிலவுகிறது என்றும் சுட்டிக்காட்டியிருக்கின்றனர்.<br><br><br></p>', 1, 19, 1, 'uploads/news/jp_6a4f2e1aac0181.45196268.png', '', 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', 0, 1, 0, 0, 'published', 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', 'டீ, காபி விலை எகிற போகுது! பால் விலை உயர்வு.. தமிழகம் முழுவதும் அமலுக்கு வருகிறது புது ரேட்!', '2026-07-09 05:14:02', '2026-07-09 10:44:02', '2026-07-10 12:19:49'),
(44, 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', 'வயநாடு-நிலச்சரிவு-டேங்கர்-லாரியால்-உயிர்-தப்பினோம்-மதுரை-தம்பதி-கண்ணீர்-மல்க-பேட்டி', 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', '<p>கோவை: கேரள மாநிலம் வயநாடு அருகே மேப்பாடி அருகே கல்லாடி பகுதியில் சுரங்கப் பாதை அமைக்கும் இடத்தில் மிகப்பெரிய நிலச்சரிவு ஏற்பட்டது. அப்போது அந்த சாலையில் சென்று கொண்டிருந்த டேங்கர் லாரியை நிலச்சரிவு அடித்துக்கொண்டு 100 மீட்டர் தள்ளிவிட்டது. அப்படி டேங்கர் லாரி குறுக்கே வந்து நின்றதால் நிலச்சரிவில் சிக்காமல் உயிர்தப்பி உள்ளார்கள் மதுரை தம்பதி.. என்ன நடந்தது என்பதை கண்ணீர்மல்க விளக்கி உள்ளார்கள்.<br>கேரள மாநிலம் வயநாடு மாவட்டத்தில் நிலச்சரிவு ஏற்படுவதற்கு அதிக வாய்ப்பு உள்ள பகுதிகள் நிறையவே உள்ளன. அங்குள்ள மேப்பாடி நிலச்சரிவு அபாயம் அதிகம் உள்ள பகுதியாகும். அந்த மேம்பாடி அருகே உள்ள பகுதி கல்லாடி. இங்கு சுரங்கப் பாதை அமைக்கும் பணி நடந்து வந்தது. இந்த இடத்தில் கடந்த ஜூலை 7ம் தேதி திடீரென நிலச்சரிவு ஏற்பட்டது. கண்ணிமைக்கும் நேரத்தில் மீனாட்சி பாலத்தை கடந்தவாறு டேங்கர் லாரி அடித்து வரப்பட்டது.<br>இதில் அடித்து வரப்பட்ட டேங்கர் லாரிக்கு அடியில் சிக்கி தமிழகத்தின் மதுரை பகுதியை சேர்ந்த பால்ராஜ், கூடம்மா தம்பதி காயங்களுடன் அதிர்ஷ்டவசமாக உயிர் தப்பி உள்ளாரகள். இந்த காட்சி அங்கு பொருத்தப்பட்டு இருந்த கேமராவில் பதிவாகி இருந்தது. டேங்கர் லாரி மற்றும் ஜீப் காரணமாக அவர்கள் உயிர் தப்பினார்கள்.<br><br>நிலச்சரிவில் சிக்கி உயிர் தப்பியது குறித்து மதுரைச் சேர்ந்த பால்ராஜ், கூடம்மா தம்பதி கூறுகையில்,\"என்னுடைய அப்பா காலத்தில் மதுரையில் இருந்து வயநாட்டுக்கு குடிபெயர்ந்தேன். எனது மனைவிக்கு மதுரை திருமங்கலம் சொந்த ஊராகும். 15 ஆண்டுகளுக்கு முன்பு திருமணம் நடந்தது. குடும்பத்துடன் வயநாட்டில் வசித்து வருகிறோம்.<br><br><br></p>', 1, 3, 1, 'uploads/news/jp_6a4f2f6e42d996.99582757.png', '', 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', 0, 1, 0, 0, 'published', 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', 'வயநாடு நிலச்சரிவு.. டேங்கர் லாரியால் உயிர் தப்பினோம்.. மதுரை தம்பதி கண்ணீர் மல்க பேட்டி', '2026-07-09 05:19:42', '2026-07-09 10:49:42', '2026-07-10 12:19:49'),
(45, 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', 'ரயிலுக்குள்-முதலிரவா-பூ-அலங்காரத்துடன்-படுக்கை-புதுமண-தம்பதியின்-செயலால்-பயணிகள்-அதிர்ச்சி-வீடியோ-', 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', '<p>சென்னை: ரயிலின் முதல் வகுப்பு கூபே பெட்டியை முதலிரவு அறை போல டெக்கரேஷன் செய்து படுக்கைகளில் பூக்கள் தூவப்பட்டு இருக்கும் வீடியோ ஒன்று சமூக வலைத்தளங்களில் வெளியாகி அதிர்ச்சியை ஏற்படுத்தியுள்ளது. அந்த வீடியோவில், இடம் பெற்ற காட்சிகளில் சொகுசு ஹோட்டலின் \'ஹனிமூன் சூட்\' போல பிரமாண்டமாக கூபே முழுவதும் அலங்கரிக்கப்பட்டு இருந்தன.<br><br>அறையின் கூரையில் சிவப்பு மற்றும் வெள்ளை நிற பலூன்களாலும், இருக்கைகளில் இதயம் போன்று ரோஜா இதழ்களாலும், அறையின் பிற பகுதிகள் மலர் மாலைகள் மற்றும் மலர்களாலும், ஏறும் படிக்கட்டுகளில் செயற்கை விளக்குகளாலும் அலங்கரிக்கப்பட்டிருந்தன. மேலும் அறையின் மேல் படுக்கையில் \'\'ஐ லவ் யூ\'\' என்ற எழுத்துக்களும் வீடியோவில் இடம் பெற்று இருந்தன.<br>டெக்கரேட்டரை வர வைத்து அலங்காரம் சமூக வலைத்தளங்களில் பரவிய இந்த வீடியோ பயணிகள் மத்தியில் அதிர்ச்சியை ஏற்படுத்திய நிலையில், ரயில்வே நிர்வாகத்தை டேக் செய்து பலரும் கேள்வி எழுப்பியிருந்தனர். இதையடுத்து, இது குறித்து விசாரணையை தொடங்கிய ரயில்வே நிர்வாகம், ரயிலின் டிக்கெட் பரிசோதகரை இடைநீக்கம் செய்துள்ளது. மகராஷ்டிரா மாநிலம் ஜல்னா ரயில் நிலையத்தில் இருந்து புறப்பட்ட ரயிலின் ஏ.சி. வகுப்பு அறையில்தான் இந்த அலங்காரம் செய்யப்பட்டு இருந்ததை ரயில்வே கண்டறிந்தது.<br><br>கூபேவை புக் செய்த ஜோடி, ஆன்லைன் வழியாக பிரைவேட் டெக்கரேட்டரை வரவைத்து, ரயில் பெட்டியை அலங்காரம் செய்துள்ளனர். புதுமண தம்பதியினருக்காக ஏற்பாடு செய்வது போல இந்த அலங்காரம் செய்யப்பட்டுள்ளது. அலங்கரிக்கப்பட்ட அந்த அறையின் வீடியோவை சமூக வலைதளங்களில் டெக்கரேஷன் செய்த தனியார் நிறுவனமே பகிர்ந்ததாக சொல்லப்படுகிறது. எனினும், பயணித்தவர்கள் யார்? என்ற விவரங்கள் தெரியவில்லை.<br><br><br></p>', 1, 11, 1, 'uploads/news/jp_6a4f31fe78db17.46235931.png', '', 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', 0, 1, 0, 0, 'published', 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', 'ரயிலுக்குள் முதலிரவா? பூ அலங்காரத்துடன் படுக்கை.. புதுமண தம்பதியின் செயலால் பயணிகள் அதிர்ச்சி! வீடியோ', '2026-07-09 05:30:38', '2026-07-09 11:00:38', '2026-07-10 12:19:49'),
(46, 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', 'ஆர்வக்கோளாறு-ரீல்ஸ்-மோகம்-என்ன-சாதிச்சீட்டிங்க-பத்திரிகையாளர்-லட்சுமணன்-காட்டம்-வீடியோ', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', '<p>சென்னை: \"அமைச்சர்களின் ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்..\" என அமைச்சர் கீர்த்தனாவின் செயலை மூத்த பத்திரிகையாளர் லட்சுமணன் விமர்சித்துள்ளார். மேலும் கூறிய அவர், \"ஆங்கிலம் தெரியாதது பெரிய குற்றமா? தமிழ் நல்லா தெரிந்தால் அதை விட பெருமை எதுவும் இல்லை என்று நான் சொல்வேன். ரீல்ஸ் மோகத்தில் போய் விழுகாதீங்க.. கீர்த்தனாவுடைய பொன்னாகவோ, தங்கையாகவோ இருந்து இருந்தால் இப்படி வெளியில் விட்டு அசிங்கப்படுவதை வேடிக்கை பார்ப்போமா.. அதனால் நீங்க என்ன சாதிச்சீங்க..\" என கேள்வி எழுப்பியுள்ளார்.<br><br>சிவகாசி அரசுப் பள்ளியில் தமிழ்நாடு தொழில்துறை அமைச்சர் கீர்த்தனா மேற்கொண்ட ஆய்வு கடும் சர்ச்சையை ஏற்படுத்தியுள்ள நிலையில், மூத்த பத்திரிகையாளர் லட்சுமணன் அமைச்சர்களின் செயல்பாடு பற்றி காட்டமாக பேசியுள்ளார். இது பற்றி ஒன் இந்தியா யூடியூப் சேனலுக்கு அவர் கூறியதாவது:-<br>அசிங்கப்படுவதை வேடிக்கை பார்ப்போமா.. ஆர்வக்கோளாறு, ரீல்ஸ் எடுக்கனும், அது வெளியில் வரவேண்டும் என்ற அந்த போதையில் சிக்கியதன் விளைவுதான் அது. அது தனிநபராக இருக்கட்டும் அமைச்சர்களாகட்டும்.. எல்லா கட்சியிலும் அந்த மோகம் இருக்கும். அமைச்சர்களாக இருப்பவர்களுக்கு கொஞ்சம் கட்டுப்பாடு அவசியம். மாண்புமிகு அமைச்சர்தான். மாண்புக்கு பின்னாடி ஆயிரம் அர்த்தங்கள் இருக்கிறது. பொறுப்புகள் இருக்கிறது.<br><br>எம்.எல்.ஏக்களுக்கு பயிற்சி வகுப்பு நடத்தியது போல அமைச்சர்களுக்கும் பயிற்சி வகுப்பு நடத்தினால் தவறு அல்ல.. பொதுவெளியில் எதை பேச வேண்டும் எதை பேசக்கூடாது என்று சொல்லிக்கொடுக்க வேண்டும். அந்த பொண்ணுக்கு ஆங்கிலம் தெரியுதோ? தெரியலயோ?.. அதை வீடியோ எடுத்து உலகம் முழுக்க பார்ப்பது போல செய்வது ஏன் என்றுதான் கேட்கிறோம். கீர்த்தனாவுடைய பொன்னாக இருந்து, அவருடைய தங்கையாக இருந்து இருந்தால் இப்படி வெளியில் விட்டு அசிங்கப்படுவதை வேடிக்கை பார்ப்போமா.. அதனால் நீங்க என்ன சாதிச்சீங்க.. நான் ரீல்ஸ் எடுக்கவில்லை, ஊடகங்கள் என்றால், ஊடகங்கள் எதற்காக வகுப்பறைக்குள் போக வேண்டும்.<br><br></p>', 1, 1, 1, 'uploads/news/jp_6a4f37d3c34e46.56149279.png', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', 0, 1, 0, 2, 'published', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', 'ஆர்வக்கோளாறு.. ரீல்ஸ் மோகம்.. என்ன சாதிச்சீட்டிங்க? பத்திரிகையாளர் லட்சுமணன் காட்டம்! வீடியோ', '2026-07-09 05:55:31', '2026-07-09 11:25:31', '2026-07-10 12:19:49'),
(47, 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', 'மகாராஷ்டிராவை-குறி-வைக்கும்-இயற்கை-அதிகாலையில்-அதிர்ந்த-பூமி-நிலநடுக்கத்தால்-மக்கள்-அச்சம்', 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', '<p>மும்பை: கனமழையால் மகாராஷ்டிரா கடுமையாக பாதிக்கப்பட்டிருக்கிறது. இப்படி இருக்கையில் இன்று காலை திடீரென நிலநடுக்கம் ஏற்பட்டிருக்கிறது. இதனால் மக்கள் அச்சமடைந்திருக்கின்றனர்.<br><br>இன்று அதிகாலை 1.30 மணிக்கு தொடங்கி 3.30 வரை அடுத்தடுத்து நில அதிர்வுகள் ஏற்பட்டிருக்கிறது. மராத்வாடா பிராந்தியத்தில் உள்ள நந்தேடு, ஹிங்கோலி மற்றும் பர்பானி ஆகிய மாவட்டங்களில் நில அதிர்வு உணரப்பட்டிருக்கிறது.<br><br>ரிக்டர் அளவுகோலில் இந்த நிலநடுக்கங்கள் 3.6 முதல் 4.6 வரை பதிவாகியுள்ளதாக அதிகாரிகள் தெரிவித்துள்ளனர். நிலநடுக்கம் லேசானது என்பதால் பெரிய அளவில் பாதிப்பு ஏற்படவில்லை.<br><br><br></p>', 2, 8, 1, 'uploads/news/jp_6a4f39761dc4e8.24780052.png', '', 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', 0, 1, 0, 0, 'published', 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', 'மகாராஷ்டிராவை குறி வைக்கும் இயற்கை! அதிகாலையில் அதிர்ந்த பூமி! நிலநடுக்கத்தால் மக்கள் அச்சம்!', '2026-07-09 06:02:30', '2026-07-09 11:32:30', '2026-07-10 12:19:49');
