INSERT INTO `tbl_slider` (`id`, `title`, `slug`, `subtitle`, `content`, `image`, `link_url`, `sort_order`, `status`, `created_at`) VALUES
(1, 'TVK alliance reunioned', 'tvk-alliance-reunioned', 'TVK Vs DMK  Blast News', 'சென்னை: தமிழக அரசியலில் தமிழக வெற்றிக் கழகம் (TVK) மற்றும் திராவிட முன்னேற்றக் கழகம் (DMK) இடையேயான மோதல் நாளுக்கு நாள் தீவிரமடைந்து வருகிறது.\r\n\r\nசமீபத்திய அரசியல் சம்பவங்கள் குறித்து இரு கட்சிகளும் ஒருவரை ஒருவர் கடுமையாக விமர்சித்து வருகின்றன. சட்டமன்றம் முதல் சமூக வலைதளங்கள் வரை அரசியல் விவாதங்கள் சூடுபிடித்துள்ளன.\r\n\r\nTVK தரப்பு, தங்கள் கட்சி மற்றும் அரசுக்கு எதிராக திட்டமிட்ட அரசியல் நடவடிக்கைகள் நடைபெறுவதாக குற்றம்சாட்டியுள்ளது. இதற்கு பதிலளித்துள்ள DMK, அந்த குற்றச்சாட்டுகளை முழுமையாக மறுத்து, அவை அரசியல் நோக்கத்துடன் கூறப்படுவதாக தெரிவித்துள்ளது.\r\n\r\nஇதற்கிடையில், கரூர் சம்பவம் மற்றும் பிற அரசியல் விவகாரங்களைச் சுற்றியும் இரு கட்சிகளுக்கு இடையே கடும் கருத்து மோதல் நீடித்து வருகிறது. இது தொடர்பான வழக்குகள் மற்றும் அரசியல் விவாதங்களும் கவனம் பெற்றுள்ளன.', 'uploads/slider/jp_6a3e5403694485.38457523.jpg', '', 1, 1, '2026-06-25 15:24:32'),
(2, 'சதரங்க ஒலிம்பியாட் – இந்தியா 5 தங்கம்', NULL, 'சாதனை படைத்த இந்திய சதரங்க வீரர்கள்', NULL, 'uploads/slider/jp_6a43482471a565.75872966.jpg', '', 2, 1, '2026-06-27 21:00:00'),
(3, 'சென்சக்ஸ் 85,000 சரித்திர உச்சம்', NULL, 'பங்குச் சந்தையில் புதிய சாதனை', NULL, 'uploads/slider/jp_6a434844418fe4.14082990.jpg', '', 3, 1, '2026-06-29 09:30:00'),
(4, 'இந்தியா vs இங்கிலாந்து டெஸ்ட் தொடர்', NULL, 'லார்ட்ஸ் மைதானத்தில் போட்டி தொடங்கியது', NULL, 'uploads/slider/jp_6a434860374268.62530729.jpg', '', 4, 1, '2026-06-29 06:00:00'),
(5, 'தமிழ்நாடு வரவு-செலவு 2026 அறிவிப்பு', NULL, 'விவசாயிகளுக்கு கடன் தள்ளுபடி', NULL, 'uploads/slider/jp_6a43487b5288e0.53434942.jpg', '', 5, 1, '2026-06-28 08:00:00'),
(6, 'யூரோ 2026 – ஸ்பெயின் அரையிறுதியில்', NULL, 'யாமால் இரட்டை கோல் வெற்றி', NULL, 'uploads/slider/jp_6a43488db427e7.96567207.jpg', '', 6, 1, '2026-06-28 22:00:00'),
(7, 'ஹைட்ராக்ஸிகுளோரோகுயின் Vs கொரோனாவைரஸ்: உடலுக்குள் நடப்பது என்ன?', NULL, 'ஹைட்ராக்ஸிகுளோரோகுயின் Vs கொரோனாவைரஸ்: உடலுக்குள் நடப்பது என்ன? வட அமெரிக்காவின் கிழக்குப் பகுதியில் இருந்து ஒரு கப்பல் அந்த நாட்டின் மேற்குப் பகுதிக்கு வர வேண்டுமானால் பல்லாயிரம் கி.மீ அட்லாண்டிக் கடலில் பயணம் செய்து, தென் அமெரிக்க கண்டம் முழுவதையும்', NULL, 'uploads/slider/jp_6a5087040f3d55.15470585.png', '', 7, 1, '2026-07-10 11:15:40');
